function ladderLength(beginWord: string, endWord: string, wordList: string[]): number {
  // Ещё не посещённые слова словаря; удаление из множества = пометка visited
  const unvisited = new Set(wordList);
  if (!unvisited.has(endWord)) return 0;

  const a = 'a'.charCodeAt(0);
  let layer = [beginWord];
  let length = 1; // число слов в последовательности, включая beginWord

  while (layer.length) {
    length++;
    const next: string[] = [];
    for (const word of layer) {
      // Перебираем все слова, отличающиеся от word одной буквой
      for (let i = 0; i < word.length; i++) {
        const prefix = word.slice(0, i);
        const suffix = word.slice(i + 1);
        for (let c = 0; c < 26; c++) {
          const candidate = prefix + String.fromCharCode(a + c) + suffix;
          if (!unvisited.has(candidate)) continue; // нет в словаре или уже были
          if (candidate === endWord) return length;
          unvisited.delete(candidate);
          next.push(candidate);
        }
      }
    }
    layer = next;
  }

  // endWord недостижимо
  return 0;
}

// Время: O(N · L² · 26) — N слов, у каждого 26·L кандидатов, каждый строится за O(L)
// Память: O(N · L) — множество слов и очередь
